steps.script:
# Setup privilege: bring the P2 Witchseekers up beside the P1 Custodian Guard so
# one engagement-zoom frame holds both players' tokens.
var m = tree.root.get_node("Main")
var u = GameState.state["units"]["MIR_U_WITCHSEEKERS_C"]
var xs = [140.0, 200.0, 260.0, 320.0]
for i in range(u["models"].size()):
	u["models"][i]["position"] = {"x": xs[i], "y": 180.0}
var moved = 0
for t in m.get_node("BoardRoot/TokenLayer").get_children():
	if t.has_meta("unit_id") and str(t.get_meta("unit_id")) == "MIR_U_WITCHSEEKERS_C":
		for md in u["models"]:
			if str(md["id"]) == str(t.get_meta("model_id")):
				t.position = Vector2(md["position"]["x"], md["position"]["y"])
				moved += 1
return moved

# The pre-T08 token, rebuilt from the ring specs: no slot ring, and one band in
# the unit colour at the old single ring's place (width max(3.5, 0.18r), outer
# edge 1px inside the rim). Measured pixel-identical to the old build's
# render of this frame in token_swatch (0.0% diff).
var n = 0
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	var f = t.get_node_or_null("FactionRing")
	var s = t.get_node_or_null("SlotRing")
	if f == null or s == null:
		continue
	var b = t.base_shape.get_bounds()
	var r = min(b.size.x, b.size.y) / 2.0
	var w = max(3.5, r * 0.18)
	f.scale = Vector2.ONE * ((r - w * 0.5 - 1.0) / r)
	s.visible = false
	t.queue_redraw()
	n += 1
return n

var n = 0
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	var f = t.get_node_or_null("FactionRing")
	var s = t.get_node_or_null("SlotRing")
	if f == null or s == null:
		continue
	f.scale = Vector2.ONE * t.T08_FACTION_RING_SCALE
	s.visible = true
	t.queue_redraw()
	n += 1
return n

# The rings are PAINTED in the ring nodes' colours: sample the live frame on
# each ring's mid-line (32 angles) for the 8 framed tokens and require >= 24/32
# slot-colour and >= 18/32 faction-colour hits (measured: Witchseekers 30-32 /
# 30-31, Custodian Guard 29 / 24-25 - their art and number label sit on top of
# a few samples). The old build scores 0 slot hits (no slot ring).
var m = tree.root.get_node("Main")
var img = tree.root.get_texture().get_image()
var zoom = m.view_zoom
var sampled = 0
var bad = []
for t in m.get_node("BoardRoot/TokenLayer").get_children():
	if not t.has_meta("unit_id"):
		continue
	var uid = str(t.get_meta("unit_id"))
	if uid != "U_CUSTODIAN_GUARD_B" and uid != "MIR_U_WITCHSEEKERS_C":
		continue
	var g = t.t08_ring_geometry()
	var c0 = t.get_global_transform_with_canvas().origin
	var fcol = t.get_node("FactionRing").modulate
	var scol = t.get_node("SlotRing").modulate
	var hs = 0
	var hf = 0
	for k in range(32):
		var a = TAU * float(k) / 32.0
		var d = Vector2(cos(a), sin(a))
		var ps = c0 + d * float(g["slot_mid"]) * zoom
		var pf = c0 + d * float(g["faction_mid"]) * zoom
		var cs = img.get_pixel(int(round(ps.x)), int(round(ps.y)))
		var cf = img.get_pixel(int(round(pf.x)), int(round(pf.y)))
		if absf(cs.r - scol.r) < 0.05 and absf(cs.g - scol.g) < 0.05 and absf(cs.b - scol.b) < 0.05:
			hs += 1
		if absf(cf.r - fcol.r) < 0.05 and absf(cf.g - fcol.g) < 0.05 and absf(cf.b - fcol.b) < 0.05:
			hf += 1
	sampled += 1
	if hs < 24 or hf < 18:
		bad.append("%s/%s slot %d/32 faction %d/32" % [uid, str(t.get_meta("model_id")), hs, hf])
if sampled != 8:
	return "sampled %d framed tokens, want 8" % sampled
return "ok" if bad.is_empty() else ", ".join(bad)

# Tier A on EVERY token: both ring nodes; SlotRing = the owner's UIConstants
# slot colour; FactionRing = the unit's colour in the army data, from the
# owner's faction palette; SlotRing.scale > FactionRing.scale; both alpha
# >= 0.9; both painted.
var fp = load("res://scripts/FactionPalettes.gd")
var n = 0
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if not t.has_meta("unit_id"):
		continue
	var uid = str(t.get_meta("unit_id"))
	var u = GameState.get_unit(uid)
	var f = t.get_node_or_null("FactionRing")
	var s = t.get_node_or_null("SlotRing")
	if f == null or s == null:
		return "%s: no FactionRing/SlotRing" % uid
	var owner = int(u.get("owner", 0))
	if s.modulate != UIConstants.player_slot_color(owner):
		return "%s: SlotRing %s is not P%d's slot colour" % [uid, s.modulate.to_html(), owner]
	if f.modulate != GameState.get_unit_color(uid):
		return "%s: FactionRing %s != army-data colour %s" % [uid, f.modulate.to_html(), GameState.get_unit_color(uid).to_html()]
	var pal = []
	for c in fp.get_palette(GameState.get_faction_name(owner)):
		pal.append(c.to_html(false))
	if not f.modulate.to_html(false) in pal:
		return "%s: FactionRing %s is not in the %s palette" % [uid, f.modulate.to_html(false), GameState.get_faction_name(owner)]
	if not (s.scale.x > f.scale.x and s.scale.y > f.scale.y):
		return "%s: SlotRing.scale %s not > FactionRing.scale %s" % [uid, str(s.scale), str(f.scale)]
	if f.modulate.a < 0.9 or s.modulate.a < 0.9:
		return "%s: ring alpha %.2f / %.2f < 0.9" % [uid, f.modulate.a, s.modulate.a]
	if not (f.visible and s.visible):
		return "%s: a ring is not painted" % uid
	n += 1
return "ok %d" % n

# Tier A, named tokens. P1 Custodes: some token's FactionRing is the Custodes
# gold of the army data (FactionPalettes primary for P1's faction = d9b333)
# with SlotRing == FRIENDLY_PLAYER_TEAL. P2 Witchseekers (all 8 models):
# SlotRing == ENEMY_PLAYER_MAGENTA and FactionRing == their own army-data
# colour (P2 is also Adeptus Custodes here, so it is a Custodes palette
# colour, not blue), distinct from the slot ring.
var fp = load("res://scripts/FactionPalettes.gd")
var gold = fp.get_primary_color(GameState.get_faction_name(1)).to_html(false)
if gold != "d9b333":
	return "P1 army-data primary is %s, not Custodes gold d9b333" % gold
var p1_gold_teal = 0
var p2_witch = 0
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if not t.has_meta("unit_id"):
		continue
	var uid = str(t.get_meta("unit_id"))
	var u = GameState.get_unit(uid)
	var f = t.get_node("FactionRing")
	var s = t.get_node("SlotRing")
	var kw = u.get("meta", {}).get("keywords", [])
	if int(u.get("owner", 0)) == 1 and "ADEPTUS CUSTODES" in kw and f.modulate.to_html(false) == gold and s.modulate == UIConstants.FRIENDLY_PLAYER_TEAL:
		p1_gold_teal += 1
	if int(u.get("owner", 0)) == 2 and str(u.get("meta", {}).get("name", "")) == "Witchseekers":
		if s.modulate != UIConstants.ENEMY_PLAYER_MAGENTA:
			return "%s SlotRing %s is not ENEMY_PLAYER_MAGENTA" % [uid, s.modulate.to_html()]
		if f.modulate != GameState.get_unit_color(uid) or f.modulate == s.modulate:
			return "%s FactionRing %s is not its army colour" % [uid, f.modulate.to_html()]
		p2_witch += 1
return "p1_gold_teal=%s p2_witchseekers=%d" % [str(p1_gold_teal > 0), p2_witch]

# Mirror match: both armies draw inner colours from the same Custodes palette,
# so an inner colour is shared across the two players - and every shared one
# is told apart by the outer slot ring.
var p1 = {}
var p2 = {}
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if not t.has_meta("unit_id"):
		continue
	var owner = int(GameState.get_unit(str(t.get_meta("unit_id"))).get("owner", 0))
	var hex = t.get_node("FactionRing").modulate.to_html(false)
	var slot = t.get_node("SlotRing").modulate
	if owner == 1:
		p1[hex] = slot
	else:
		p2[hex] = slot
var shared = 0
for hex in p1:
	if p2.has(hex):
		if p1[hex] == p2[hex]:
			return "inner colour %s shared with the same outer ring" % hex
		shared += 1
return shared > 0

# The army panel (U) lists every unit with its colour swatch - the colour the
# player picks. Each unit's swatch must equal the inner ring of every one of
# its board tokens.
var panel = tree.root.get_node_or_null("Main/ArmyPanel")
if panel == null or not panel.is_visible_in_tree():
	return "army panel not open"
var layer = tree.root.get_node("Main/BoardRoot/TokenLayer")
var checked = 0
for uid in panel._label_edits:
	var swatch = panel._label_edits[uid].get_parent().get_child(0)
	var want = swatch.get_theme_stylebox("normal").bg_color.to_html(false)
	for t in layer.get_children():
		if t.has_meta("unit_id") and str(t.get_meta("unit_id")) == uid:
			var got = t.get_node("FactionRing").modulate.to_html(false)
			if got != want:
				return "%s: inner ring %s, army panel swatch %s" % [uid, got, want]
			checked += 1
return "ok %d" % checked

# Change Color through the army panel: press the Custodian Guard swatch (opens
# the faction-palette picker) and pick Pale gold (Custodes palette entry 6).
# Buttons are pressed via their signal - the same handler chain a click runs:
# picker -> GameState.set_unit_color -> panel unit_visual_changed -> Main
# refreshes the unit's tokens.
var panel = tree.root.get_node("Main/ArmyPanel")
var uid = "U_CUSTODIAN_GUARD_B"
panel._label_edits[uid].get_parent().get_child(0).pressed.emit()
var picker = panel.get_node_or_null("UnitColorPickerPopup")
if picker == null:
	return "no colour picker opened"
var grid = picker.get_child(0).get_child(1)
var fp = load("res://scripts/FactionPalettes.gd")
var want = fp.get_palette(GameState.get_faction_name(1))[6].to_html(false)
grid.get_child(6).pressed.emit()
var got = GameState.get_unit_color(uid).to_html(false)
return "ok" if got == want else "stored %s, picked %s" % [got, want]

# The panel swatch and every Custodian Guard token's inner ring show the new
# colour; the outer ring stays the P1 slot colour.
var fp = load("res://scripts/FactionPalettes.gd")
var want = fp.get_palette(GameState.get_faction_name(1))[6].to_html(false)
var panel = tree.root.get_node("Main/ArmyPanel")
var sw = panel._label_edits["U_CUSTODIAN_GUARD_B"].get_parent().get_child(0).get_theme_stylebox("normal").bg_color.to_html(false)
if sw != want:
	return "army panel swatch %s, want %s" % [sw, want]
var n = 0
for t in tree.root.get_node("Main/BoardRoot/TokenLayer").get_children():
	if t.has_meta("unit_id") and str(t.get_meta("unit_id")) == "U_CUSTODIAN_GUARD_B":
		if t.get_node("FactionRing").modulate.to_html(false) != want:
			return "%s inner ring %s, want %s" % [str(t.get_meta("model_id")), t.get_node("FactionRing").modulate.to_html(false), want]
		if t.get_node("SlotRing").modulate != UIConstants.FRIENDLY_PLAYER_TEAL:
			return "%s outer ring changed" % str(t.get_meta("model_id"))
		n += 1
return "ok %d" % n

# ...and the board paints it: sample each Custodian Guard token's ring
# mid-lines on the live frame (same thresholds as the first sample).
var m = tree.root.get_node("Main")
if m.get_node_or_null("ArmyPanel") != null:
	return "army panel still open"
var img = tree.root.get_texture().get_image()
var fp = load("res://scripts/FactionPalettes.gd")
var fcol = Color.from_string(fp.get_palette(GameState.get_faction_name(1))[6].to_html(false), Color.BLACK)
var scol = UIConstants.FRIENDLY_PLAYER_TEAL
var bad = []
var sampled = 0
for t in m.get_node("BoardRoot/TokenLayer").get_children():
	if not t.has_meta("unit_id") or str(t.get_meta("unit_id")) != "U_CUSTODIAN_GUARD_B":
		continue
	var g = t.t08_ring_geometry()
	var c0 = t.get_global_transform_with_canvas().origin
	var hs = 0
	var hf = 0
	for k in range(32):
		var a = TAU * float(k) / 32.0
		var dv = Vector2(cos(a), sin(a))
		var ps = c0 + dv * float(g["slot_mid"]) * m.view_zoom
		var pf = c0 + dv * float(g["faction_mid"]) * m.view_zoom
		var cs = img.get_pixel(int(round(ps.x)), int(round(ps.y)))
		var cf = img.get_pixel(int(round(pf.x)), int(round(pf.y)))
		if absf(cs.r - scol.r) < 0.05 and absf(cs.g - scol.g) < 0.05 and absf(cs.b - scol.b) < 0.05:
			hs += 1
		if absf(cf.r - fcol.r) < 0.05 and absf(cf.g - fcol.g) < 0.05 and absf(cf.b - fcol.b) < 0.05:
			hf += 1
	sampled += 1
	if hs < 24 or hf < 18:
		bad.append("%s slot %d/32 faction %d/32" % [str(t.get_meta("model_id")), hs, hf])
if sampled != 4:
	return "sampled %d Custodian Guard tokens, want 4" % sampled
return "ok" if bad.is_empty() else ", ".join(bad)
